alter table public.timeline_daw_normalization_support_cases add column if not exists notification_state text not null default 'none' check(notification_state in('none','pending','acknowledged')),add column if not exists cleanup_failure_count integer not null default 0 check(cleanup_failure_count>=0);create table if not exists public.timeline_daw_normalization_support_escalation_receipts(id text primary key,idempotency_key text not null unique,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,case_id text not null references public.timeline_daw_normalization_support_cases(id) on delete cascade,due_at timestamptz not null,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_escalation_receipts enable row level security;create policy timeline_daw_normalization_support_escalations_owner on public.timeline_daw_normalization_support_escalation_receipts for select to authenticated using(owner_id=auth.uid());create table if not exists public.timeline_daw_normalization_support_worker_runs(id text primary key,worker_id text not null,started_at timestamptz not null,finished_at timestamptz not null,processed integer not null,escalated integer not null,cleaned integer not null,failed integer not null,failure_messages jsonb not null default '[]',next_wakeup text not null check(next_wakeup in('scheduled','attention')),created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_worker_runs enable row level security;create table if not exists public.timeline_daw_normalization_support_worker_lease(name text primary key,lease_token text,lease_expires_at timestamptz);insert into public.timeline_daw_normalization_support_worker_lease(name) values('support-automation') on conflict do nothing;alter table public.timeline_daw_normalization_support_worker_lease enable row level security;create or replace function public.claim_timeline_daw_normalization_support_worker(p_token text,p_seconds integer default 240) returns boolean language plpgsql security definer set search_path=public as $$ declare claimed boolean;begin if current_user not in('service_role','postgres')then raise exception 'service role required';end if;update public.timeline_daw_normalization_support_worker_lease set lease_token=p_token,lease_expires_at=now()+make_interval(secs=>greatest(30,least(p_seconds,300))) where name='support-automation' and(lease_expires_at is null or lease_expires_at<now()) returning true into claimed;return coalesce(claimed,false);end $$;revoke all on function public.claim_timeline_daw_normalization_support_worker(text,integer) from public,anon,authenticated;grant execute on function public.claim_timeline_daw_normalization_support_worker(text,integer) to service_role;
